// src/catalog.js
var PRODUCTS = products_default.products;
function planId(productId, tierId) {
  return `${productId}__${tierId}`;
}
function splitPlanId(id) {
  const [product, tier] = String(id).split("__");
  return { product, tier };
}
function buyablePlans() {
  const plans = [];
  for (const p of PRODUCTS) {
    if (p.status !== "live") continue;
    for (const t of p.tiers) {
      if (!(Number(t.price_usd) > 0)) continue;
      plans.push({
        id: planId(p.id, t.id),
        name: `${p.name} ${t.name}`,
        price_usd: Number(t.price_usd),
        features: t.features || []
      });
    }
  }
  return plans;
}
function findTier(productId, tierId) {
  const p = PRODUCTS.find((x) => x.id === productId);
  const t = p && p.tiers.find((x) => x.id === tierId);
  return p && t ? { product: p, tier: t } : null;
}

